use verus::prelude::*;

verus! {

    // Finds an index `r` in the prefix `a[0..n]` such that
    // `a[r]` is a maximum over that prefix.
    //
    // Requirements:
    //   - 0 < n ≤ a.len()
    // Guarantees:
    //   - 0 ≤ r < n
    //   - ∀ i < n. a[r] ≥ a[i]
    //
    fn findMax(a: &[i32], n: usize) -> (r: usize)
        requires n > 0 && n <= a.len()
        ensures r < n
        ensures forall |i: usize| i < n ==> a[r] >= a[i]
    {
        // We keep track of the index of the current maximum,
        // starting at 0, and scan from i = 1 up to n.
        let mut max_idx: usize = 0;
        let mut i: usize = 1;

        // Loop until we've considered all positions < n
        while i < n
            invariant 1 <= i && i <= n
            invariant max_idx < i
            invariant forall |j: usize| j < i ==> a[max_idx] >= a[j]
            decreases n - i
        {
            if a[i] > a[max_idx] {
                max_idx = i;
            }
            i += 1;
        }

        // At this point, i == n, and by the invariant
        // max_idx < n and ∀ j < n. a[max_idx] ≥ a[j].
        r = max_idx;
    }

} // end verus!